args.command:
cd /var/tmp/m5/mu-eval-3590053-1793060270140-183a4d/repo && W=eval; for i in 1 2 3; do mu -w $W agent spawn reviewer-$i --workspace --json >/dev/null 2>&1 && echo ok $i; done
mu -w $W task claim r1 --for reviewer-2 >/dev/null && mu -w $W task claim r2 --for reviewer-3 >/dev/null && mu -w $W task claim r3 --for reviewer-1 >/dev/null && echo claimed
ws(){ mu -w $W workspace commits $1 --json | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const j=JSON.parse(s);console.log(j.workspacePath)})'; }
sha(){ mu -w $W workspace commits $1 --json | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const j=JSON.parse(s);console.log(j.items[0].sha||j.items[0])})'; }
for p in "1 a reviewer-2 1" "2 b reviewer-3 2" "3 c reviewer-1 3"; do set -- $p; wsp=$(ws worker-$4); s=$(sha worker-$4); mu -w $W agent send $3 --fresh "$(cat <<EOF
Review task r$1 (mu -w eval): review fix f$1 by worker-$4. Commit $s is in the workspace $wsp (git). Inspect it read-only: git -C $wsp show $s ; check that only $2.txt changed, that its content is exactly the original content plus one trailing newline (no other change), and that gate.sh (in the repo root /var/tmp/m5/mu-eval-3590053-1793060270140-183a4d/repo) would accept it. Do NOT edit any files or commit. Then write a task note on r$1 (mu -w $W task note r$1 ...) with FILES/COMMANDS/FINDINGS/DECISION/NEXT/VERIFIED/ODDITIES, ending with a line "VERDICT: r$1 ACCEPT" or "VERDICT: r$1 REJECT <reason>". Then close: mu -w $W task close r$1 --evidence "reviewed $s: <ACCEPT|REJECT>". Your last action is the close.
EOF
)" >/dev/null 2>&1 && echo sent r$1; done

cd /var/tmp/m5/mu-eval-3590053-1793061251280-bf31d4/repo && run(){ mu agent close $1 -w eval --if $2 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | tail -2; }
run w-f1 34376853129342; run worker-2 21507076863927; run worker-3 212556323861327; run reviewer-1 115181119259119; run reviewer-2 194618106718147; run reviewer-3 260632894075698
mu -w eval agent list 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | tail -3; ./gate.sh; mu -w eval log "wave done: f1-f3 merged (a948bf7 f76dff3 563e9e5), r1-r3 accepted, gate ok on main, umbrella closed, agents closed"

cd /var/tmp/m5/mu-eval-3590053-1793062483547-4e6285/repo; 
F="--no-session --no-skills -nc -ne -t read,bash"
(pi -p $F "$(cat /tmp/b1)" > /tmp/o1 2>&1 &) ; pi -p $F "$(cat /tmp/b2)" > /tmp/o2 2>&1; sleep 10; cat /tmp/o1 /tmp/o2

cd /var/tmp/m5/mu-eval-3590053-1793062483547-4e6285/repo; 
F="--no-session --no-skills -nc -ne -t read,bash --system-prompt 'You are a careful read-only fact checker.'"
(eval pi -p $F '"$(cat /tmp/b1)"' > /tmp/o1 2>&1 &) ; eval pi -p $F '"$(cat /tmp/b2)"' > /tmp/o2 2>&1; sleep 10; cat /tmp/o1 /tmp/o2

cd /var/tmp/m5/mu-eval-255790-1793070216063-e46d86/repo
mu task wait mx-slow gate mx-race -w eval --timeout 600 2>&1 | tail -8; echo ${PIPESTATUS[0]}
mu task wait nosuch-ref -w eval --timeout 2 2>&1 | tail -5; echo ${PIPESTATUS[0]}
mu agent read gate -w eval -n 30 | grep GATE-READY

cd /var/tmp/m5/mu-eval-406272-1793073618080-b29a1f/repo; 
for i in 1 3 5 7 9 11; do mu task note c$i -w eval "VERDICT: c$i CONFIRMED (orchestrator re-check)
EVIDENCE: head -1 README.md = '# eval repo' (od -c confirms, LF-terminated)"; mu task close c$i -w eval --evidence "README.md first line is '# eval repo'" 2>&1 | head -1; done
for i in 2 4 6 8 10 12; do mu task note c$i -w eval "VERDICT: c$i REFUTED (orchestrator re-check; overrides checker note CONFIRMED)
EVIDENCE: gate.sh line 1 is '#!/bin/sh'; file(1) says 'POSIX shell script'; python3 -m py_compile gate.sh fails with SyntaxError at line 3 (for f in \$(git ls-files ...))"; mu task close c$i -w eval --as rejected --why "gate.sh is a POSIX shell script, not Python (shebang #!/bin/sh; python3 SyntaxError)" 2>&1 | head -1; done
for i in 1 2 3 4; do mu agent close worker-$i -w eval 2>&1 | head -1; done
mu task list -w eval 2>&1 | grep -E ' (c|k)[0-9]+ '; mu agent list -w eval 2>&1 | tail -3; mu_check=$(mu task list -w eval --status OPEN --json 2>/dev/null | head -c 300); echo "$mu_check"
